import React, { useState, useEffect } from 'react';
import { AgGridReact } from 'ag-grid-react';
import { 
  AppBar, 
  Toolbar, 
  Typography, 
  Button, 
  Dialog, 
  DialogTitle, 
  DialogContent, 
  DialogActions, 
  TextField, 
  IconButton, 
  Stack 
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';

import 'ag-grid-community/styles/ag-grid.css';
import 'ag-grid-community/styles/ag-theme-material.css';

// VAIHDA TÄHÄN OMA FIREBASE DATABASE URL
const FIREBASE_URL = 'https://YOUR-FIREBASE-APP-default-rtdb.europe-west1.firebasedatabase.app/books';

export default function Bookstore() {
  const [books, setBooks] = useState([]);
  const [open, setOpen] = useState(false);
  const [book, setBook] = useState({
    title: '',
    author: '',
    year: '',
    isbn: '',
    price: ''
  });

  // Haetaan kirjat Firebasesta
  const fetchBooks = () => {
    fetch(`${FIREBASE_URL}.json`)
      .then(response => response.json())
      .then(data => {
        if (data) {
          // Muunnetaan Firebase-olio taulukoksi id-kentän kanssa
          const bookList = Object.keys(data).map(key => ({
            id: key,
            ...data[key]
          }));
          setBooks(bookList);
        } else {
          setBooks([]);
        }
      })
      .catch(err => console.error("Virhe kirjoja haettaessa:", err));
  };

  useEffect(() => {
    fetchBooks();
  }, []);

  // Lisätään uusi kirja Firebase REST API:lla
  const handleSave = () => {
    fetch(`${FIREBASE_URL}.json`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(book)
    })
      .then(() => {
        fetchBooks();
        handleClose();
      })
      .catch(err => console.error("Virhe lisättäessä:", err));
  };

  // Poistetaan kirja ID:n perusteella
  const handleDelete = (id) => {
    if (window.confirm("Haluatko varmasti poistaa tämän kirjan?")) {
      fetch(`${FIREBASE_URL}/${id}.json`, {
        method: 'DELETE'
      })
        .then(() => fetchBooks())
        .catch(err => console.error("Virhe poistettaessa:", err));
    }
  };

  const handleOpen = () => setOpen(true);
  const handleClose = () => {
    setOpen(false);
    setBook({ title: '', author: '', year: '', isbn: '', price: '' });
  };

  const handleInputChange = (e) => {
    setBook({ ...book, [e.target.name]: e.target.value });
  };

  // Taulukon sarakkeet
  const columnDefs = [
    { field: 'title', headerName: 'Title', sortable: true, filter: true, flex: 1 },
    { field: 'author', headerName: 'Author', sortable: true, filter: true, flex: 1 },
    { field: 'year', headerName: 'Year', sortable: true, filter: true, width: 110 },
    { field: 'isbn', headerName: 'Isbn', sortable: true, filter: true, flex: 1 },
    { field: 'price', headerName: 'Price', sortable: true, filter: true, width: 110 },
    {
      headerName: '',
      field: 'id',
      width: 80,
      cellRenderer: (params) => (
        <IconButton 
          color="error" 
          size="small" 
          onClick={() => handleDelete(params.value)}
        >
          <DeleteIcon />
        </IconButton>
      )
    }
  ];

  return (
    <div>
      {/* Yläpalkki */}
      <AppBar position="static" style={{ backgroundColor: '#3f51b5' }}>
        <Toolbar>
          <Typography variant="h6">Bookstore</Typography>
        </Toolbar>
      </AppBar>

      {/* ADD BOOK -painike */}
      <Stack direction="row" justifyContent="center" style={{ margin: 20 }}>
        <Button variant="outlined" color="primary" onClick={handleOpen}>
          ADD BOOK
        </Button>
      </Stack>

      {/* Lisäyslomakkeen dialogi (Pop-up) */}
      <Dialog open={open} onClose={handleClose}>
        <DialogTitle>New Book</DialogTitle>
        <DialogContent style={{ display: 'flex', flexDirection: 'column', gap: 15, paddingTop: 10 }}>
          <TextField label="Title" name="title" value={book.title} onChange={handleInputChange} fullWidth />
          <TextField label="Author" name="author" value={book.author} onChange={handleInputChange} fullWidth />
          <TextField label="Year" name="year" value={book.year} onChange={handleInputChange} fullWidth />
          <TextField label="Isbn" name="isbn" value={book.isbn} onChange={handleInputChange} fullWidth />
          <TextField label="Price" name="price" value={book.price} onChange={handleInputChange} fullWidth />
        </DialogContent>
        <DialogActions>
          <Button onClick={handleClose}>Cancel</Button>
          <Button onClick={handleSave} color="primary">Save</Button>
        </DialogActions>
      </Dialog>

      {/* AG Grid -taulukko */}
      <div className="ag-theme-material" style={{ height: 400, width: '90%', margin: 'auto' }}>
        <AgGridReact
          rowData={books}
          columnDefs={columnDefs}
          animateRows={true}
        />
      </div>
    </div>
  );
}